import * as React from "react";

export function LightningBoltCanvas({ className = "w-full h-full min-h-[260px]" }: { className?: string }): React.JSX.Element {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  React.useEffect(() => {
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext("2d")!;
    let w = (canvas.width = canvas.parentElement?.clientWidth ?? 600);
    let h = (canvas.height = canvas.parentElement?.clientHeight ?? 300);
    let animId: number;
    function bolt(x1: number, y1: number, x2: number, y2: number, depth: number) {
      if (depth <= 0) { ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); return; }
      const mx = (x1 + x2) / 2 + (Math.random() - 0.5) * 60 / depth;
      const my = (y1 + y2) / 2 + (Math.random() - 0.5) * 60 / depth;
      bolt(x1, y1, mx, my, depth - 1);
      bolt(mx, my, x2, y2, depth - 1);
      if (Math.random() < 0.4) bolt(mx, my, mx + (Math.random() - 0.5) * 80, my + Math.random() * 60, depth - 2);
    }
    const draw = () => {
      ctx.fillStyle = "rgba(5,6,18,0.3)";
      ctx.fillRect(0, 0, w, h);
      if (Math.random() < 0.15) {
        ctx.strokeStyle = "rgba(150, 180, 255, 0.9)";
        ctx.lineWidth = 1.5;
        ctx.shadowColor = "#8ab4ff";
        ctx.shadowBlur = 12;
        ctx.beginPath();
        bolt(Math.random() * w, 0, Math.random() * w, h, 6);
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
      animId = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(animId);
  }, []);
  return <div className={className}><canvas ref={canvasRef} className="w-full h-full block" /></div>;
}

import * as React from "react";
import { LightningBoltCanvas } from "./lightning-bolt-canvas";

export default function LightningBoltCanvasDemo(): React.JSX.Element {
  return (
    <div className="relative flex min-h-[480px] w-full overflow-hidden rounded-2xl bg-neutral-950 border border-neutral-800">
      {/* Background canvas layer */}
      <LightningBoltCanvas className="absolute inset-0 h-full w-full" />

      {/* Foreground content layer */}
      <div className="relative z-10 flex h-full w-full flex-col items-center justify-center p-8 text-center my-auto">
        <span className="rounded-full border border-white/15 bg-white/10 px-3.5 py-1 text-xs font-mono font-medium text-neutral-300 backdrop-blur-md">
          Ambient Canvas Engine
        </span>
        <h2 className="mt-4 text-3xl sm:text-5xl font-bold tracking-tight text-white">
          Lightning Bolt Canvas
        </h2>
        <p className="mt-3 max-w-md text-sm sm:text-base text-neutral-400">
          Hardware-accelerated ambient visuals that react seamlessly to viewport and pointer interactions.
        </p>
      </div>
    </div>
  );
}
